        </div>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.TrackingNumber" placeholder="Tracking #" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.Origin" placeholder="Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.Destination" placeholder="Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.CustomerEmail" placeholder="Customer Email" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" @bind="newShipment.Description" placeholder="Description" />
                </div>
                <div class="col-md-3">
