@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using System.Net.Http.Json
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Dispatch Dashboard</h1>

<div class="mb-3">
    <div class="row g-2 align-items-end">
        <div class="col-auto">
            <label class="form-label">Filter by Status</label>
            <select class="form-select" @bind="statusFilter">
                <option value="">All</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-auto">
            <label class="form-label">Search Destination</label>
            <input type="text" class="form-control" @bind="searchDestination" @bind:event="oninput" placeholder="Search..." />
        </div>
        <div class="col-auto">
            <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
        </div>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.TrackingNumber" placeholder="Tracking #" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.Origin" placeholder="Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.Destination" placeholder="Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" @bind="newShipment.CustomerEmail" placeholder="Customer Email" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" @bind="newShipment.Description" placeholder="Description" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Ship Date</label>
                    <input type="date" class="form-control" @bind="newShipment.ShippedDate" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-2 d-flex align-items-end gap-2">
                    <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.CustomerEmail</td>
                    <td>
                        <select class="form-select form-select-sm"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string statusFilter = "";
    private string searchDestination = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? new()).Where(s =>
            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter) &&
            (string.IsNullOrEmpty(searchDestination) || s.Destination.Contains(searchDestination, StringComparison.OrdinalIgnoreCase)));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private void ShowCreateForm()
    {
        showCreateForm = true;
        newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
    }

    private async Task CreateShipment()
    {
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            showCreateForm = false;
            await LoadShipments();
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status", new { Status = newStatus });
            shipment.Status = newStatus;
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using System.Net.Http.Json
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" placeholder="Enter tracking number..." />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>Tracking: @trackedShipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(trackedShipment.Status) fs-6">@trackedShipment.Status</span></dd>
                        <dt>Description</dt>
                        <dd>@trackedShipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@trackedShipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@trackedShipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fw-bold text-primary">@trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                        @if (trackedShipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd class="text-success">@trackedShipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                        }
                    </dl>
                </div>
            </div>
            <div class="mt-3">
                <h6>Delivery Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(trackedShipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercent(trackedShipment.Status)%">
                        @trackedShipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

<h3 class="mt-4">My Shipments</h3>
@if (myShipments == null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in myShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td><button class="btn btn-sm btn-outline-primary" @onclick="() => ViewDetails(shipment.TrackingNumber)">Details</button></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string trackingNumber = "";
    private string? errorMessage;
    private ShipmentDto? trackedShipment;
    private List<ShipmentDto>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        errorMessage = null;
        trackedShipment = null;

        if (string.IsNullOrWhiteSpace(trackingNumber))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        var response = await Http.GetAsync($"/api/shipments/track/{trackingNumber.Trim()}");
        if (response.IsSuccessStatusCode)
        {
            trackedShipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
        }
        else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            errorMessage = "Shipment not found. Please check the tracking number.";
        }
        else
        {
            errorMessage = "Unable to retrieve shipment information.";
        }
    }

    private void ViewDetails(string tracking)
    {
        trackingNumber = tracking;
        _ = TrackShipment();
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-secondary"
    };

    private string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-primary"
    };

    private int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Exception => 50,
        _ => 0
    };
}

