### 4. Create API endpoints on the server

Create file `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using System.Security.Claims;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers only)
        group.MapGet("/", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var roles = user.Claims.Where(c => c.Type == ClaimTypes.Role).Select(c => c.Value);
            if (!roles.Contains("Dispatcher"))
                return Results.Forbid();

            var shipments = await db.Shipments
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    ActualDelivery = s.ActualDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Description = s.Description
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Update shipment status (dispatchers only)
        group.MapPut("/{id:int}/status", async (int id, UpdateStatusRequest request, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var roles = user.Claims.Where(c => c.Type == ClaimTypes.Role).Select(c => c.Value);
            if (!roles.Contains("Dispatcher"))
                return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            shipment.Status = request.Status;
            if (request.Status == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok();
        });

        // Create shipment (dispatchers only)
        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var roles = user.Claims.Where(c => c.Type == ClaimTypes.Role).Select(c => c.Value);
            if (!roles.Contains("Dispatcher"))
                return Results.Forbid();

            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = dto.Status,
                ShippedDate = dto.ShippedDate,
                EstimatedDelivery = dto.EstimatedDelivery,
                CustomerEmail = dto.CustomerEmail,
                Description = dto.Description
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                ShippedDate = shipment.ShippedDate,
                EstimatedDelivery = shipment.EstimatedDelivery,
                CustomerEmail = shipment.CustomerEmail,
                Description = shipment.Description
            });
        });

        // Track shipment by tracking number (customers)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
            var roles = user.Claims.Where(c => c.Type == ClaimTypes.Role).Select(c => c.Value);

            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null)
                return Results.NotFound();

            // Dispatchers can see any shipment; customers only their own
            if (!roles.Contains("Dispatcher") && 
                !string.Equals(shipment.CustomerEmail, email, StringComparison.OrdinalIgnoreCase))
                return Results.Forbid();

            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                ShippedDate = shipment.ShippedDate,
                EstimatedDelivery = shipment.EstimatedDelivery,
                ActualDelivery = shipment.ActualDelivery,
                CustomerEmail = shipment.CustomerEmail,
                Description = shipment.Description
            });
        });

        // Get shipments for current customer
        group.MapGet("/my", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);

            var shipments = await db.Shipments
                .Where(s => s.CustomerEmail.ToLower() == (email ?? "").ToLower())
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    ActualDelivery = s.ActualDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Description = s.Description
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });
    }
}

public record UpdateStatusRequest(ShipmentStatus Status);
```

